import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allowlist for sort columns - but note this only covers ORDER BY
    private static final Set<String> VALID_SORT_COLS = new HashSet<>(Arrays.asList(
        "created_at", "amount", "status", "customer_name"
    ));

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String category = req.getParameter("category");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        // Validate sort column against allowlist
        if (sortCol == null || !VALID_SORT_COLS.contains(sortCol)) {
            sortCol = "created_at";
        }

        // Validate date format (basic check)
        if (dateFrom != null && !dateFrom.matches("\\d{4}-\\d{2}-\\d{2}")) {
            dateFrom = null;
        }
        if (dateTo != null && !dateTo.matches("\\d{4}-\\d{2}-\\d{2}")) {
            dateTo = null;
        }

        // HTML-encode category for display purposes later
        String displayCategory = StringEscapeUtils.escapeHtml4(category);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {

            // Build query - category is used in WHERE clause
            StringBuilder sql = new StringBuilder();
            sql.append("SELECT id, customer_name, amount, status, created_at ");
            sql.append("FROM transactions WHERE 1=1 ");

            if (dateFrom != null) {
                sql.append("AND created_at >= '" + dateFrom + "' ");
            }
            if (dateTo != null) {
                sql.append("AND created_at <= '" + dateTo + "' ");
            }
            if (category != null && !category.isEmpty()) {
                // Developer note: category values come from a dropdown,
                // but we filter by prefix match for sub-categories
                sql.append("AND category LIKE '" + category + "%' ");
            }

            sql.append("ORDER BY " + sortCol + " DESC");

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql.toString());

            resp.setContentType("text/html; charset=UTF-8");
            PrintWriter out = resp.getWriter();
            out.println("<html><body>");
            out.println("<h2>Report: " + displayCategory + "</h2>");
            out.println("<table border='1'>");
            out.println("<tr><th>ID</th><th>Customer</th><th>Amount</th><th>Status</th><th>Date</th></tr>");

            while (rs.next()) {
                out.println("<tr>");
                out.println("<td>" + rs.getInt("id") + "</td>");
                out.println("<td>" + StringEscapeUtils.escapeHtml4(rs.getString("customer_name")) + "</td>");
                out.println("<td>" + rs.getDouble("amount") + "</td>");
                out.println("<td>" + StringEscapeUtils.escapeHtml4(rs.getString("status")) + "</td>");
                out.println("<td>" + rs.getString("created_at") + "</td>");
                out.println("</tr>");
            }

            out.println("</table></body></html>");

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }
}
